import json
from copy import deepcopy

# Define categories and values
categories = {
    "Name": ["Arnold", "Carol", "Peter", "Eric", "Bob", "Alice"],
    "style": ["ranch", "colonial", "modern", "craftsman", "mediterranean", "victorian"],
    "lunch": ["pizza", "stew", "spaghetti", "grilled cheese", "stir fry", "soup"],
    "vacation": ["cultural", "cruise", "mountain", "camping", "city", "beach"],
    "height": ["average", "very tall", "very short", "short", "tall", "super tall"],
    "cigar": ["yellow monster", "prince", "dunhill", "pall mall", "blue master", "blends"]
}

all_positions = set(range(1, 7))

# Utility for variable key
def var_key(cat, val):
    return (cat, val)

# Constraint base class
class Constraint:
    def propagate(self, domains):
        return False  # return True if any domain changed

# Equality: var1 == var2
class EqConstraint(Constraint):
    def __init__(self, v1, v2):
        self.v1 = v1
        self.v2 = v2
    def propagate(self, domains):
        d1 = domains[self.v1]
        d2 = domains[self.v2]
        inter = d1 & d2
        changed = False
        if inter != d1:
            domains[self.v1] = inter
            changed = True
        if inter != d2:
            domains[self.v2] = inter
            changed = True
        return changed

# var1 is left of var2: pos(var1) < pos(var2)
class LeftOfConstraint(Constraint):
    def __init__(self, v1, v2):
        self.v1 = v1
        self.v2 = v2
    def propagate(self, domains):
        d1 = domains[self.v1]
        d2 = domains[self.v2]
        if not d1 or not d2:
            return False
        # Keep x in d1 if exists y in d2 with x < y
        max_d2 = max(d2)
        new_d1 = {x for x in d1 if x < max_d2}
        # Keep y in d2 if exists x in d1 with x < y
        min_d1 = min(d1)
        new_d2 = {y for y in d2 if y > min_d1}
        changed = False
        if new_d1 != d1:
            domains[self.v1] = new_d1
            changed = True
        if new_d2 != d2:
            domains[self.v2] = new_d2
            changed = True
        return changed

# var1 is directly left of var2: pos(var1) + 1 == pos(var2)
class DirectLeftOfConstraint(Constraint):
    def __init__(self, v1, v2):
        self.v1 = v1
        self.v2 = v2
    def propagate(self, domains):
        d1 = domains[self.v1]
        d2 = domains[self.v2]
        new_d1 = {x for x in d1 if (x + 1) in d2 and 1 <= x <= 5}
        new_d2 = {y for y in d2 if (y - 1) in d1 and 2 <= y <= 6}
        changed = False
        if new_d1 != d1:
            domains[self.v1] = new_d1
            changed = True
        if new_d2 != d2:
            domains[self.v2] = new_d2
            changed = True
        return changed

# |var1 - var2| == d
class DistanceConstraint(Constraint):
    def __init__(self, v1, v2, d):
        self.v1 = v1
        self.v2 = v2
        self.d = d
    def propagate(self, domains):
        d1 = domains[self.v1]
        d2 = domains[self.v2]
        new_d1 = {x for x in d1 if (x + self.d) in d2 or (x - self.d) in d2}
        new_d2 = {y for y in d2 if (y + self.d) in d1 or (y - self.d) in d1}
        changed = False
        if new_d1 != d1:
            domains[self.v1] = new_d1
            changed = True
        if new_d2 != d2:
            domains[self.v2] = new_d2
            changed = True
        return changed

# Not at a specific position
class NotPositionConstraint(Constraint):
    def __init__(self, v, p):
        self.v = v
        self.p = p
    def propagate(self, domains):
        if self.p in domains[self.v]:
            domains[self.v] = set(x for x in domains[self.v] if x != self.p)
            return True
        return False

# Position equals constant
class PositionConstraint(Constraint):
    def __init__(self, v, p):
        self.v = v
        self.p = p
    def propagate(self, domains):
        if domains[self.v] != {self.p}:
            domains[self.v] = {self.p}
            return True
        return False

# All-different within a category
class AllDifferentConstraint(Constraint):
    def __init__(self, vars_in_cat):
        self.vars = vars_in_cat[:]  # list of variable keys
    def propagate(self, domains):
        # Remove assigned positions from others
        changed = False
        assigned = [next(iter(domains[v])) for v in self.vars if len(domains[v]) == 1]
        for v in self.vars:
            if len(domains[v]) > 1:
                new_dom = domains[v] - set(assigned)
                if new_dom != domains[v]:
                    domains[v] = new_dom
                    changed = True
        return changed

def make_domains():
    domains = {}
    for cat, vals in categories.items():
        for v in vals:
            domains[(cat, v)] = set(all_positions)
    return domains

def build_constraints():
    cons = []

    # Fixed positions
    cons.append(PositionConstraint(var_key("Name", "Alice"), 5))  # 1
    cons.append(PositionConstraint(var_key("Name", "Eric"), 4))   # 9

    # From 14 and 3: Alice is the person who loves the spaghetti eater, and that person resides in a Victorian house
    cons.append(PositionConstraint(var_key("style", "victorian"), 5))  # Victorian at house 5
    cons.append(EqConstraint(var_key("Name", "Alice"), var_key("style", "victorian")))  # Alice is in Victorian

    # 2 and 7: stir fry = colonial; average = stir fry
    cons.append(EqConstraint(var_key("lunch", "stir fry"), var_key("style", "colonial")))
    cons.append(EqConstraint(var_key("height", "average"), var_key("lunch", "stir fry")))

    # 6: Craftsman not in 3
    cons.append(NotPositionConstraint(var_key("style", "craftsman"), 3))

    # 8, 15, 22: beach = ranch; tall = beach; ranch = blue master
    cons.append(EqConstraint(var_key("vacation", "beach"), var_key("style", "ranch")))
    cons.append(EqConstraint(var_key("height", "tall"), var_key("vacation", "beach")))
    cons.append(EqConstraint(var_key("style", "ranch"), var_key("cigar", "blue master")))

    # 11, 12: mountain = yellow monster; mountain = very tall
    cons.append(EqConstraint(var_key("vacation", "mountain"), var_key("cigar", "yellow monster")))
    cons.append(EqConstraint(var_key("vacation", "mountain"), var_key("height", "very tall")))

    # 13: mountain next to Dunhill
    cons.append(DistanceConstraint(var_key("vacation", "mountain"), var_key("cigar", "dunhill"), 1))

    # 17: stir fry directly left of Bob
    cons.append(DirectLeftOfConstraint(var_key("lunch", "stir fry"), var_key("Name", "Bob")))

    # 20: stir fry left of Prince
    cons.append(LeftOfConstraint(var_key("lunch", "stir fry"), var_key("cigar", "prince")))

    # 10: one house between colonial and camping
    cons.append(DistanceConstraint(var_key("style", "colonial"), var_key("vacation", "camping"), 2))

    # 16: tall left of Victorian
    cons.append(LeftOfConstraint(var_key("height", "tall"), var_key("style", "victorian")))

    # 18: modern left of Alice
    cons.append(LeftOfConstraint(var_key("style", "modern"), var_key("Name", "Alice")))

    # 19: craftsman left of short
    cons.append(LeftOfConstraint(var_key("style", "craftsman"), var_key("height", "short")))

    # 21: two houses between grilled cheese and super tall
    cons.append(DistanceConstraint(var_key("lunch", "grilled cheese"), var_key("height", "super tall"), 3))

    # 23: blends directly left of blue master
    cons.append(DirectLeftOfConstraint(var_key("cigar", "blends"), var_key("cigar", "blue master")))

    # 24: cultural = pizza
    cons.append(EqConstraint(var_key("vacation", "cultural"), var_key("lunch", "pizza")))

    # 25: pizza left of cruise
    cons.append(LeftOfConstraint(var_key("lunch", "pizza"), var_key("vacation", "cruise")))

    # 4: Arnold = stew
    cons.append(EqConstraint(var_key("Name", "Arnold"), var_key("lunch", "stew")))

    # 5: one house between average and Peter
    cons.append(DistanceConstraint(var_key("height", "average"), var_key("Name", "Peter"), 2))

    # Additional pruning from simple implications:
    # From direct-left relations, ensure sources not at 6 and targets not at 1
    cons.append(NotPositionConstraint(var_key("lunch", "stir fry"), 6))
    cons.append(NotPositionConstraint(var_key("cigar", "blends"), 6))
    cons.append(NotPositionConstraint(var_key("cigar", "blue master"), 1))
    cons.append(NotPositionConstraint(var_key("lunch", "pizza"), 6))
    cons.append(NotPositionConstraint(var_key("vacation", "cruise"), 1))

    # All-different per category
    all_diff_constraints = []
    for cat, vals in categories.items():
        vars_in_cat = [var_key(cat, v) for v in vals]
        all_diff_constraints.append(AllDifferentConstraint(vars_in_cat))

    return cons, all_diff_constraints

def propagate_all(domains, constraints, all_diff_constraints):
    changed = True
    while changed:
        changed = False
        # Apply all constraints
        for c in constraints:
            if c.propagate(domains):
                changed = True
                # Early failure
                for v, d in domains.items():
                    if len(d) == 0:
                        return False
        # Apply all-different constraints
        for ad in all_diff_constraints:
            if ad.propagate(domains):
                changed = True
                for v, d in domains.items():
                    if len(d) == 0:
                        return False
    return True

def is_complete(domains):
    return all(len(d) == 1 for d in domains.values())

def select_unassigned_variable(domains):
    # Minimum Remaining Values
    items = [(len(d), k) for k, d in domains.items() if len(d) > 1]
    if not items:
        return None
    items.sort()
    return items[0][1]

def backtrack(domains, constraints, all_diff_constraints):
    if not propagate_all(domains, constraints, all_diff_constraints):
        return None
    if is_complete(domains):
        return domains
    var = select_unassigned_variable(domains)
    if var is None:
        return None
    domain_values = sorted(domains[var])
    for val in domain_values:
        new_domains = deepcopy(domains)
        new_domains[var] = {val}
        result = backtrack(new_domains, constraints, all_diff_constraints)
        if result is not None:
            return result
    return None

def solve():
    domains = make_domains()
    constraints, all_diff_constraints = build_constraints()
    solution_domains = backtrack(domains, constraints, all_diff_constraints)
    if solution_domains is None:
        raise RuntimeError("No solution found")

    # Build per-house mapping
    houses = {i: {} for i in range(1, 7)}
    # Invert mapping per category
    for cat, vals in categories.items():
        for val in vals:
            pos = next(iter(solution_domains[(cat, val)]))
            houses[pos][cat] = val

    # Prepare output rows
    header = ["House", "Name", "style", "lunch", "vacation", "height", "cigar"]
    rows = []
    for i in range(1, 7):
        row = [
            str(i),
            houses[i]["Name"],
            houses[i]["style"],
            houses[i]["lunch"],
            houses[i]["vacation"],
            houses[i]["height"],
            houses[i]["cigar"],
        ]
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, indent=2))
